from:
.v2.is-play .v2-ostg.has-rank .v2-q2fast{animation:v2-slam calc(.55s * var(--fx-scale)) var(--v2-pop) both,v2-q2vis calc(var(--rk) - 3s * var(--fx-scale)) linear;}
.v2 .v2-q2flag{position:absolute;left:50%;bottom:var(--axis-b,240px);z-index:3;display:flex;flex-direction:column;align-items:center;transform:translateX(-50%);}
.v2 .v2-q2flag i{width:8px;height:330px;background:#E5484D;border-radius:4px;}
.v2 .v2-q2flag-t{padding:8px 26px;border-radius:16px;background:#E5484D;color:#FFFFFF;font-weight:900;font-size:52px;white-space:nowrap;}
.v2.is-play .v2-q2flag{animation:v2-q2flag calc(.5s * var(--fx-scale)) ease-in both;}
@keyframes v2-q2flag{0%{transform:translate(-50%,-110vh);}75%{transform:translate(-50%,0);}88%{transform:translate(-50%,-26px);}100%{transform:translate(-50%,0);}}
.v2 .v2-q2far{position:absolute;bottom:calc(var(--axis-b,240px) + 40px);z-index:3;display:flex;flex-direction:column;gap:2px;max-width:24%;
  padding:6px 18px;border-radius:16px;background:var(--wc2);font-weight:900;}
.v2 .v2-q2far.is-left{left:0;align-items:flex-start;}
.v2 .v2-q2far.is-right{right:0;align-items:flex-end;}
.v2 .v2-q2far b{font-size:44px;line-height:1.25;}
.v2 .v2-q2far small{max-width:100%;font-size:42px;line-height:1.25;margin-top:8px;}
.v2.is-play .v2-q2far{animation:v2-ofade calc(.25s * var(--fx-scale)) ease both;}
/* 1位の発表：照明が落ちる → ドラムロール1.5秒 → スポットライトが1人に → 名前が大きく・紙ふぶき（点滅しない）→ 順位 */
.v2 .v2-q2champ{position:relative;height:430px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;overflow:hidden;}
.v2 .v2-q2c-dim{position:absolute;inset:-200px;background:rgba(6,6,16,.45);opacity:0;}
.v2.is-play .v2-q2c-dim{animation:v2-ddim calc(2.2s * var(--fx-scale)) ease;}
.v2 .v2-q2c-spot{position:absolute;left:50%;top:-40px;width:900px;height:560px;margin-left:-450px;pointer-events:none;
  background:radial-gradient(ellipse 50% 60% at 50% 30%,rgba(255,240,190,.55),rgba(255,240,190,0) 70%);}
.v2.is-play .v2-q2c-spot{animation:v2-ofade calc(.3s * var(--fx-scale)) ease both;animation-delay:calc(1.5s * var(--fx-scale));}
.v2 .v2-q2c-hd{position:relative;font-weight:900;font-size:60px;padding:4px 34px;border-radius:999px;background:var(--won);color:var(--wi);}
.v2 .v2-q2c-nm{position:relative;max-width:92%;font-weight:900;font-size:170px;line-height:1.05;padding:8px 50px;border-radius:36px;background:var(--wi);color:var(--won);}
.v2.is-play .v2-q2c-nm{animation:v2-slam calc(.55s * var(--fx-scale)) var(--v2-pop) both;animation-delay:calc(1.5s * var(--fx-scale));}
.v2 .v2-q2conf{position:absolute;top:-30px;width:24px;height:14px;border-radius:3px;background:var(--c);opacity:0;}
.v2.is-play .v2-q2conf{animation:v2-q2conf calc(2s * var(--fx-scale)) ease-in both;}
@keyframes v2-q2conf{0%{opacity:0;transform:translateY(0) rotate(0);}6%{opacity:1;}100%{opacity:0;transform:translateY(520px) rotate(540deg);}}
.v2 .v2-q2c-rk{display:flex;flex-direction:column;gap:12px;}
.v2.is-play .v2-q2c-rk{animation:v2-rise var(--v2-move) var(--v2-ease) both;animation-delay:calc(2.3s * var(--fx-scale));}
/* ---- 指示68-5 の直し（Claude チャットが動画を見て・10/28）：舞台・字の大きさ・重なり。上の同じ名前の決まりより後ろに置いて上書きする ----
   舞台：暗い床・上からスポットライト3本（円すい）・名前の壁はうすく。TV 1920×1080 で 名前の札は高さ48px 以上・問題文は64px 以上
   （docs/指示66/tools/check.js の「TVの名前の札が小さい」「TVの問題文が小さい」が見張る） */
.v2 .v2-tvc.is-stage2 .v2-circles{display:none;}
.v2 .v2-tvc.is-stage2 .v2-nr{color:color-mix(in srgb,var(--wi) 4%,transparent);}
.v2 .v2-tvc.is-stage2::before{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;
  background:radial-gradient(ellipse 72% 20% at 50% 100%,rgba(255,236,190,.12),rgba(255,236,190,0) 72%),
    linear-gradient(180deg,rgba(4,5,18,.52),rgba(4,5,18,.82));}
.v2 .v2-tvc.is-stage2::after{
  background:conic-gradient(from 166deg at 18% -4%,rgba(255,244,205,0) 0deg,rgba(255,244,205,.13) 6deg 22deg,rgba(255,244,205,0) 28deg),
    conic-gradient(from 163deg at 50% -4%,rgba(255,244,205,0) 0deg,rgba(255,244,205,.17) 7deg 27deg,rgba(255,244,205,0) 34deg),
    conic-gradient(from 166deg at 82% -4%,rgba(255,244,205,0) 0deg,rgba(255,244,205,.13) 6deg 22deg,rgba(255,244,205,0) 28deg);
  -webkit-mask-image:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4));mask-image:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4));}
/* 答えている間：問題の札は真ん中で大きく光る。答えの札は字を札の真ん中に大きく（記号は左上） */
.v2 .v2-q2tv .v2-q2qa{text-align:center;padding:28px 48px;border-color:#FFE58A;
  box-shadow:0 0 0 4px rgba(255,229,138,.35),0 0 120px rgba(255,229,138,.45);}
.v2 .v2-q2tv .v2-q2qa .v2-otq{font-size:80px;}
.v2 .v2-q2tv .v2-och{position:relative;justify-content:center;text-align:center;padding:96px 24px 28px;font-size:80px;line-height:1.15;}
.v2 .v2-q2tv .v2-ochs.is-n4 .v2-och{font-size:68px;}
.v2 .v2-q2tv .v2-och .v2-okey{position:absolute;left:22px;top:22px;}
/* 開く（早答え）：問題文 64px。答えの札は1行（字・人数）にして、上を名前の札と「いちばん早かった人」にあける */
.v2 .v2-q2tv .v2-ounv.is-tv .v2-oqs{font-size:64px;line-height:1.2;}
.v2 .v2-q2tv .v2-ocol{position:relative;z-index:1;}
.v2 .v2-q2tv .v2-ocard{flex-wrap:nowrap;min-height:0;margin-top:8px;padding:10px 20px;}
.v2 .v2-q2tv .v2-ocard-t{font-size:48px;}
.v2 .v2-q2tv .v2-ocnt{flex:none;}
.v2 .v2-q2tv .v2-ocnt b{font-size:72px;}
.v2 .v2-q2tv .v2-ocol.is-right .v2-ocard{box-shadow:0 0 70px rgba(255,216,74,.7);}
/* まちがいの山は、名前の札が出る時にしまう（札と玉が重ならない） */
.v2 .v2-q2tv .v2-ocol.is-wrong .v2-opile{visibility:hidden;}
.v2.is-play .v2-q2tv .v2-ocol.is-wrong .v2-opile{animation:v2-q2vis var(--tg) linear;}
@keyframes v2-q2vis{from,to{visibility:visible;}}
/* 正解：スポットライト（上からの円すい）が札から札へゆれて、正解の札で止まる。札のうしろを照らす */
.v2 .v2-q2tv .v2-q2hops{z-index:0;top:-300px;}
.v2 .v2-q2tv .v2-q2hop{top:0;bottom:-10px;border:0;border-radius:0;box-shadow:none;
  background:linear-gradient(180deg,rgba(255,240,190,.04),rgba(255,240,190,.46));clip-path:polygon(38% 0,62% 0,100% 100%,0 100%);}
/* いちばん早かった人：名前の箱は画面の幅の半分より広く（字の大きさは長さで決める・v2-quiz2.js bigFs） */
.v2 .v2-q2tv .v2-q2fast{gap:12px;}
.v2 .v2-q2tv .v2-q2fast small{font-size:48px;}
.v2 .v2-q2fast-r{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:12px 28px;max-width:100%;}
.v2 .v2-q2tv .v2-q2fast b{min-width:960px;max-width:min(1440px,100%);line-height:1.1;padding:26px 40px;text-align:center;}
